// Generates server/workflows/bundled-content.ts from the vendored markdown in
// server/workflows/bundled. Inlining the bodies as string literals keeps bundled
// workflows readable by a compiled executable, which has no source tree to read.

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseSkillDocument, TICKET_WORKFLOW_LIMITS } from '../common/ticket-workflows.ts';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const bundledDir = path.join(root, 'server', 'workflows', 'bundled');
const outputFile = path.join(root, 'server', 'workflows', 'bundled-content.ts');

async function readWorkflows() {
  const entries = await fs.readdir(bundledDir, { withFileTypes: true });
  const workflows = [];
  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
    if (!entry.isDirectory()) continue;
    const skillFile = path.join(bundledDir, entry.name, 'SKILL.md');
    let raw;
    try {
      raw = await fs.readFile(skillFile, 'utf8');
    } catch {
      continue;
    }
    const document = parseSkillDocument(raw);
    if (!document.body) {
      throw new Error(`Bundled workflow ${entry.name} has no instruction body.`);
    }
    // The frontmatter name is the workflow's own label; a description is prose
    // about it and reads badly in a menu.
    workflows.push({
      id: entry.name,
      title: (document.name ?? entry.name).slice(0, TICKET_WORKFLOW_LIMITS.titleCodePoints),
      body: document.body,
    });
  }
  if (workflows.length === 0) throw new Error('No bundled workflows were found.');
  return workflows;
}

function render(workflows) {
  const entries = workflows
    .map(({ id, title, body }) =>
      `  {\n    id: ${JSON.stringify(id)},\n    title: ${JSON.stringify(title)},\n`
      + `    source: { kind: 'bundled', path: null },\n    body: ${JSON.stringify(body)},\n  },`,
    )
    .join('\n');
  return [
    '// Generated by scripts/build-bundled-workflows.js from server/workflows/bundled.',
    '// Run `bun run build:workflows` after editing any file in that directory.',
    '',
    "import type { TicketWorkflow } from '../../common/ticket-workflows.js';",
    '',
    'export const BUNDLED_TICKET_WORKFLOWS: readonly TicketWorkflow[] = [',
    entries,
    '];',
    '',
  ].join('\n');
}

const workflows = await readWorkflows();
await fs.writeFile(outputFile, render(workflows), 'utf8');
console.log(`Generated ${workflows.length} bundled workflows: ${workflows.map((w) => w.id).join(', ')}`);
